/// Calls `accounting_apply` of the Vesper library `umem` (`vesper_umem_accounting_apply`).
pub fn accounting_apply(counts: &mut Vec<u32>, kind: u32) -> bool {
    // SAFETY: `vesper_umem_accounting_apply` has exactly this signature in the export ABI; every
    // pointer is a live, writable buffer of the size the ABI requires, and
    // every handle passed is owned or borrowed as its mode requires.
    let raw = vesper_port_abi::with_seq_mut(RUNTIME, counts, |seq_counts| unsafe { vesper_umem_accounting_apply(seq_counts, kind as i64) });
    raw != 0
}

